{
  "findings": [
    {
      "ref": "[D530]",
      "area": "money",
      "claim": "A nine-year-old spent $118,000 on YouTube ads using a corporate credit card saved in a shared Google account.",
      "stance": "risk",
      "quote": "according to a video his father posted on September 15, 2026. The father, who goes by Dave in the coverage, says the money came off a company credit card that had been saved to the family’s shared Google account after an earlier purchase of Robux, Roblox’s in-game currency."
    },
    {
      "ref": "[D530]",
      "area": "money",
      "claim": "The child expanded the ad campaigns and ran them for three weeks, resulting in roughly $118,000 in charges.",
      "stance": "risk",
      "quote": "the child kept the campaigns running and expanding, spinning up additional pushes under names like “Mighty Mike” and “Epic Roblox” that targeted his own gameplay uploads. Three weeks later, Dave says his company’s finance department called him into a room with his manager and a corporate representative and showed him a spending table totaling $118,000, all billed to the corporate card."
    },
    {
      "ref": "[D530]",
      "area": "money",
      "claim": "The corporate card had no spending cap and was reused without additional approval for the ad platform.",
      "stance": "mitigation",
      "quote": "Google’s payment system stores card details in what it calls a [payments profile](https://myaccount.google.com/payments-and-subscriptions), a single record tied to the account that can be reused across Google properties, including Google Ads, Google Play, and YouTube. Once that profile existed, the card was available for the child to use again, this time inside the ad platform, without a second approval step or a spending ceiling attached to the account."
    },
    {
      "ref": "[D530]",
      "area": "money",
      "claim": "The corporate card was saved to a personal Google account for a small Robux purchase and later used for large ad spend without re‑authentication.",
      "stance": "mitigation",
      "quote": "He says he had previously entered his company card into the family’s Google account to buy Robux for his son. Google’s payment system stores card details in what it calls a [payments profile](https://myaccount.google.com/payments-and-subscriptions), a single record tied to the account that can be reused across Google properties, including Google Ads, Google Play, and YouTube."
    },
    {
      "ref": "[D530]",
      "area": "data",
      "claim": "The story illustrates that Google’s unified payments profile can link purchases across unrelated services, allowing a child to access a corporate card without extra checks.",
      "stance": "risk",
      "quote": "it is a live demonstration of how Google’s unified payments profile links purchases across totally unrelated services, and how little friction stands between “buy some Robux” and “launch four-figure ad campaigns” once a card is saved."
    },
    {
      "ref": "[D530]",
      "area": "age_gating",
      "claim": "The age‑gate for ad platform access did not work in practice; a nine‑year‑old could run large ad campaigns.",
      "stance": "risk",
      "quote": "Google Ads accounts, unless a manual budget cap is set at the campaign or account level, will continue serving and billing ads up to whatever the card can absorb. A corporate card, unlike many personal consumer cards, often carries a high limit and few automated fraud triggers for a category like online advertising, since ad spend is a routine business expense."
    },
    {
      "ref": "[D530]",
      "area": "developer_record",
      "claim": "The father’s employer has not confirmed any termination or repayment demand, so no regulatory or legal action is documented yet.",
      "stance": "neutral",
      "quote": "No outlet has published an invoice, an ad‑account screenshot, or a statement from his employer confirming a termination, a suspension, or a formal repayment demand."
    }
  ]
}
